// Small authored French lexicon. This is intentionally a game vocabulary, not a full dictionary.
const lexicon={article:'le la les un une des du',noun:'chat chats rat rats usine usines robot robots mot mots texte textes lettre lettres phrase phrases soleil lune or nuit jour vent monde plume livre livres code jeu jeux art ami amis mer terre arbre arbres vie temps pain feu air eau roi reine',verb:'lit écrit tourne rêve avance brille aime voit crée chante parle joue vole vit rit dort est sont marche change imagine grandit',adjective:'petit petite grand grande libre calme rapide lent belle beau bleu verte rouge doux douce nouveau nouvelle',connector:'et car donc puis mais avec sans dans sous sur pour de à',adverb:'vite bien loin ici toujours encore ensemble',pronoun:'il elle on nous vous tu je'};
export const DICTIONARY=Object.entries(lexicon).flatMap(([tag,words])=>words.split(' ').map(text=>({text,tag})));
export const LEXICON=new Map(DICTIONARY.map(w=>[w.text,w]));
export const normalize=t=>t.toLocaleLowerCase('fr-FR');
export const isWord=t=>LEXICON.has(normalize(t));
export function tokens(p){return p.tokens||[p.text]}
export function value(p){if(p.kind==='dust')return 1;if(p.kind==='letter')return 2;if(p.kind==='word')return p.text.length*(isWord(p.text)?12:4);if(p.kind==='sentence'&&p.valid)return Math.ceil(scoreSentence(p).score*10*(1+Math.log2(1+tokens(p).length)/5));return Math.max(1,p.text.length*2)}
export const CATEGORY_LABELS={article:'article',noun:'nom',verb:'verbe',adjective:'adjectif',connector:'connecteur',adverb:'adverbe',pronoun:'pronom'};
export const TEMPLATES=[
 {id:'simple',name:'Phrase simple',pattern:['article','noun','verb'],research:'syntax'},
 {id:'object',name:'Avec un complément',pattern:['article','noun','verb','article','noun'],research:'objects'},
 {id:'adjective',name:'Avec un adjectif',pattern:['article','adjective','noun','verb'],research:'adjectives'},
 {id:'compound',name:'Deux propositions',pattern:['article','noun','verb','connector','article','noun','verb'],research:'connectors'}
];
export const templateFor=m=>TEMPLATES.find(t=>t.id===m.template)||TEMPLATES[0];
export function templateMissing(list,pattern){const have={};list.forEach(t=>{const tag=LEXICON.get(normalize(t))?.tag;have[tag]=(have[tag]||0)+1});const missing={};for(const tag of pattern){if(have[tag])have[tag]--;else missing[tag]=(missing[tag]||0)+1}return missing}
export function arrangeTemplate(list,pattern){const remaining=[...list],ordered=[];for(const tag of pattern){const i=remaining.findIndex(t=>LEXICON.get(normalize(t))?.tag===tag);if(i<0)return null;ordered.push(...remaining.splice(i,1))}return [...ordered,...remaining]}
export function scoreSentence(p){const list=tokens(p),tags=list.map(t=>LEXICON.get(normalize(t))?.tag),matched=[...TEMPLATES].reverse().find(t=>t.pattern.every((tag,i)=>tags[i]===tag));const words=list.length,chars=Array.from(p.text).length,adjectives=tags.filter(t=>t==='adjective').length,connectors=tags.filter(t=>t==='connector').length;const structure=matched?12+matched.pattern.length*2:0,details=adjectives*8+connectors*12;return{score:chars+words*2+structure+details,wordCount:words,characterCount:chars,template:matched?.id||null,complexity:{characters:chars,words:words*2,structure,details},structured:!!matched}}
export function validation(p,syntax=false,template='simple'){const list=tokens(p),reasons=[];if(list.length<3)reasons.push('au moins 3 mots');if(!list.every(isWord))reasons.push('mots du dictionnaire');if(p.text.replace(/[.,!?:;]$/u,'').toLowerCase()!==list.join(' ').toLowerCase())reasons.push('espaces entre les mots');if(!/^[A-ZÀ-Þ]/u.test(p.text))reasons.push('majuscule initiale');if(!/[.!?]$/u.test(p.text))reasons.push('point, ! ou ? final');const tags=list.map(t=>LEXICON.get(normalize(t))?.tag),pattern=TEMPLATES.find(t=>t.id===template)?.pattern||TEMPLATES[0].pattern;if(syntax&&!pattern.every((tag,i)=>tags[i]===tag))reasons.push('modèle '+pattern.map(t=>CATEGORY_LABELS[t]).join(' → '));return{valid:reasons.length===0,reasons,...scoreSentence(p)}}
/** @typedef {{kind:'dust'|'letter'|'word'|'phrase'|'sentence',text:string,born:number,category?:string,languageType?:string,valid?:boolean,tokens?:string[],score?:number,wordCount?:number,characterCount?:number}} FactoryItem */
export function enrich(p){if(p.kind==='letter')p.category='aeiouyàâéèêîôùû'.includes(normalize(p.text))?'vowel':'consonant';if(p.kind==='word'){p.valid=isWord(p.text);p.languageType=LEXICON.get(normalize(p.text))?.tag||null}if(p.kind==='sentence')Object.assign(p,scoreSentence(p));return p}
